/* ─────────────────────────────────────────────────────────────
   Women's → Resource Library → suggested author/speaker catalog.

   Curated, read-only starter list of well-known women's ministry
   authors and speakers, each with their notable devotionals,
   books, and Bible study walkthroughs. This is browse + save only
   — there's no add/edit UI for this catalog. Women tap into an
   author's page and save individual works to their own list
   (see SavedResources.jsx / womens:saved-resources).
   ───────────────────────────────────────────────────────────── */

export const WORK_TYPE_META = {
  devotional:   { label: 'Devotional',   icon: '🕊️' },
  book:         { label: 'Book',         icon: '📘' },
  'bible-study': { label: 'Bible Study', icon: '📖' },
  song:         { label: 'Song',         icon: '🎵' },
  commentary:   { label: 'Commentary',   icon: '📜' },
};
export const WORK_TYPE_ORDER = ['devotional', 'book', 'bible-study', 'song', 'commentary'];

/** Thematic "aspect" tags applied per-work (not just per-author) so the
 *  Resource Library can filter authors down to only the specific books
 *  that touch a given theme, with an accurate per-author match count. */
export const ASPECT_LIST = [
  'Prayer',
  'Spiritual Warfare',
  'Anxiety & Fear',
  'Grief & Suffering',
  'Identity & Worth',
  'Grace',
  'Forgiveness',
  'Marriage & Relationships',
  "Parenting & Children's",
  'Prophecy & End Times',
  'Theology & Bible Study',
  'Emotional Healing',
  'Purpose & Calling',
  'Daily Devotional',
  'Gratitude',
  'Faith & Trust',
  'Fiction & Story',
];

/** Fallback-safe lookup — legacy/imported works may carry types
 *  outside the three above, so render a sane default instead of
 *  crashing on an unrecognized key. */
export function getWorkTypeMeta(type) {
  if (type && WORK_TYPE_META[type]) return WORK_TYPE_META[type];
  const label = type ? type.charAt(0).toUpperCase() + type.slice(1) : 'Resource';
  return { label, icon: '📄' };
}

